using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor;
namespace CodexOutTransfer {
public static class LocateOutTree {
const string W="C:/Users/lenovo/Documents/Codex/2026-10-16/new-chat/work/";
static string Path(Transform t){return t.parent?Path(t.parent)+"/"+t.name:t.name;}
[MenuItem("Tools/Out Scene Transfer/Reveal Located Tree In Scene View")]
public static void Reveal(){var s=SceneManager.GetSceneByPath("Assets/ArtStyleTest/Scenes/out.unity");var root=s.GetRootGameObjects().First(g=>g.name=="SM_Env_Tree_Meadow_02 (1)");bool hidden=SceneVisibilityManager.instance.IsHidden(root);SceneVisibilityManager.instance.Show(root,true);Selection.activeGameObject=root;EditorGUIUtility.PingObject(root);if(SceneView.lastActiveSceneView)SceneView.lastActiveSceneView.FrameSelected(false);SceneView.RepaintAll();File.AppendAllText(W+"out_right_tree_location.txt","\nrootSelected="+root.name+" rootWasHidden="+hidden+" nowSceneHidden="+SceneVisibilityManager.instance.IsHidden(root)+" sceneViewFramed=True gameCameraUntouched=True\n");}
[MenuItem("Tools/Out Scene Transfer/Locate Right Background Tree")]
public static void Locate(){var b=new StringBuilder();try{var scene=SceneManager.GetSceneByPath("Assets/ArtStyleTest/Scenes/out.unity");var roots=scene.GetRootGameObjects();var c=roots.SelectMany(g=>g.GetComponentsInChildren<Camera>(true)).First(c=>c.transform.parent&&c.transform.parent.name=="xiangjipingtai");b.AppendLine("camera="+c.transform.position+" rot="+c.transform.eulerAngles+" aspect="+c.aspect);var candidates=new Dictionary<Transform,Bounds>();foreach(var r in roots.SelectMany(g=>g.GetComponentsInChildren<Renderer>(false)).Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.sharedMaterials.Any(m=>m&&m.shader&&(m.shader.name.Contains("Foliage")||m.name.Contains("Pine"))))){Transform tree=r.transform;for(var t=r.transform;t&&t.parent;t=t.parent){if(t.GetComponent<LODGroup>()||t.name.StartsWith("SM_Env_Tree_")||t.name=="Layered irregular pine"||t.name=="Foreground bare pine"){tree=t;break;}}if(candidates.ContainsKey(tree)){var box=candidates[tree];box.Encapsulate(r.bounds);candidates[tree]=box;}else candidates.Add(tree,r.bounds);}
Transform selected=null;float scoreBest=float.NegativeInfinity;foreach(var pair in candidates){var bounds=pair.Value;var p=c.WorldToViewportPoint(bounds.center);if(p.z<=0||p.x<.45f||p.x>1.5f||p.y<.40f||p.y>2.8f)continue;float angular=bounds.size.magnitude/p.z;bool hidden=SceneVisibilityManager.instance.IsHidden(pair.Key.gameObject);b.AppendLine("tree="+Path(pair.Key)+" position="+pair.Key.position+" bounds="+bounds+" screen="+p.ToString("F3")+" angle="+angular.ToString("F3")+" sceneHidden="+hidden+" hideFlags="+pair.Key.gameObject.hideFlags);float score=angular-Mathf.Abs(p.x-.80f)*.3f-Mathf.Abs(p.y-.85f)*.18f;if(score>scoreBest){scoreBest=score;selected=pair.Key;}}
foreach(var t in roots.SelectMany(g=>g.GetComponentsInChildren<Terrain>(false))){var data=t.terrainData;b.AppendLine("terrain="+Path(t.transform)+" trees="+data.treeInstanceCount+" drawTrees="+t.drawTreesAndFoliage);int n=0;foreach(var inst in data.treeInstances){var position=Vector3.Scale(inst.position,data.size)+t.transform.position;var p=c.WorldToViewportPoint(position);if(p.z>0&&p.x>.5f&&p.x<1.1f&&p.y>-.2f&&p.y<.9f&&n++<12)b.AppendLine("terrainTree="+position+" screen="+p.ToString("F3")+" prototype="+data.treePrototypes[inst.prototypeIndex].prefab?.name);}}
if(selected){Selection.activeGameObject=selected.gameObject;EditorGUIUtility.PingObject(selected.gameObject);b.AppendLine("selected="+Path(selected)+" score="+scoreBest);}b.AppendLine("located=True");}catch(Exception e){b.AppendLine(e.ToString());Debug.LogException(e);}File.WriteAllText(W+"out_right_tree_location.txt",b.ToString());}
}
}
